params.ts_type:
(({
  parentId?: string | null
  /** 当前选中的下一条消息；切换版本时保留每条分支原有的选择。 */
  selectedChildId?: string
}) & {
  id: string
  role: 'assistant'
  createdAt: number
  /** 未记录模型时为 null，续写使用当前默认模型。 */
  model: ('deepseek-flash' | 'deepseek-v4-pro') | null
  /** 请求时是否开启深度思考 */
  thinking?: boolean
  /** 请求时是否声明 deepseek_web_search；关闭时仍声明 deepseek_read_url */
  search?: boolean
  /** 本轮请求的系统信息快照；各回答版本独立保存，续写沿用。历史消息中缺省的快照保持为空。 */
  latestReminder?: string
  /** 是否允许作为续写前缀；仍需满足回复状态与内容限制。 */
  prefix: boolean
  status: ('pending' | 'streaming' | 'done' | 'stopped' | 'error')
  /** 可识别的内容块按接收顺序排列；续写产生的块追加在已有块之后 */
  blocks: ({
  type: 'thinking'
  thinking: string
  signature?: string
  /** content_block_start 的时间；没有事件时间的历史块缺省 */
  startedAt?: number
  /** content_block_stop（或回复结束）的时间 */
  endedAt?: number
  /** 仅有耗时、没有事件时间时保存秒数。 */
  elapsedSeconds?: number
} | {
  type: 'text'
  text: string
  citations?: ({
  type: 'web_search_result_location'
  url: string
  /** 查不到标题时为 null */
  title: string | null
  /** 当前文本块截至该引用处的全部正文（去除首尾空白） */
  cited_text: string
  /** 恒为空串 */
  encrypted_index: string
})[]
  /** 服务端提示文案，仅用于展示，不作为模型回答参与上下文或续写。 */
  isTemplate?: boolean
} | (| ({
  type: 'server_tool_use'
  /** srvtoolu_{s|ds|rl|is|dis}_{序号}_{32 位 hex} */
  id: string
  /** 文字搜索与图搜均为 deepseek_web_search；read_link 为 deepseek_read_url */
  name: 'deepseek_web_search' | 'deepseek_read_url'
  input: ServerToolInput
  caller: { type: 'direct' }
  kind: ServerToolKind
})
  | ({
  type: 'web_search_tool_result'
  tool_use_id: string
  /** 成功且无可见结果时为 []；失败时为只含一个错误项的数组 */
  content: (WebSearchResult | WebSearchToolResultError)[]
  kind: 'search' | 'deep_search' | 'image_search' | 'deep_image_search'
})
  | ({
  type: 'web_fetch_tool_result'
  tool_use_id: string
  content: WebFetchResult | WebFetchToolResultError
  kind: 'read_link' | 'deep_search'
  /** 仅 read_link 成功时返回的加密页面，多轮请求原样回传；失败及 deep_search 不返回 */
  signature?: string
})))[]
  stopReason?: ('end_turn' | 'max_tokens' | 'tool_use' | 'refusal')
  stopDetails?: { type: 'refusal'; category: null; explanation: null }
  /** 最近一次请求的用量，续写后更新 */
  usage?: {
  /** 未命中缓存的输入 Token */
  input_tokens: number
  cache_creation_input_tokens: number
  cache_read_input_tokens: number
  /** message_start 中为 0，message_delta 中为全轮累计值 */
  output_tokens: number
  /** 仅当 message_delta 中有对外输出的搜索结果块时出现 */
  server_tool_use?: { web_search_requests: number; tool_search: number }
}
  error?: {
    /** upload：发送前补传附件失败，请求没有发出 */
    kind: (| 'http'
  /** 流中返回的错误帧（如等待生成超时），随后连接关闭 */
  | 'stream'
  /** 请求没有到达服务端（断网、跨域被拦截等） */
  | 'network'
  /** 流在 message_stop 之前结束 */
  | 'interrupted'
  /** 响应不符合协议（如非 SSE 响应） */
  | 'protocol') | 'upload'
    message: string
    status?: number
    localMessage?: { key: keyof typeof zh; params?: (Record<string, string | number>) }
    /** 仅 upload：重新上传是否可能成功（网络、限流、服务端繁忙）；过大、格式不支持为 false */
    retryable?: boolean
  }
})

exports.returns:
({
  steps: ({
  type: 'search'
  /** 该步骤首次调用的 ID，空查询的图搜也有稳定标识 */
  key: string
  kind: (| 'search'
  | 'deep_search'
  | 'read_link'
  | 'image_search'
  | 'deep_image_search')
  queries: string[]
  results: ({
  url: string
  title: string
  /** 优先使用服务端站点名，没有时使用域名（去掉 www.） */
  siteName: string
  /** 搜索结果为 RFC 3339，阅读链接为爬虫提取的原始日期 */
  publishedAt: string | null
  /** 明文摘要与站点图标；缺少元数据时为 null */
  snippet: string | null
  siteIcon: string | null
  /** 引用角标与搜索结果列表上的编号，从 1 开始 */
  index: number
})[]
  status: ('wip' | 'done' | 'failed')
} | { type: 'open'; pages: {
  id: string
  url: string
  title: string
  status: ToolStatus
}[] } | {
  type: 'find'
  patterns: { id: string; pattern: string; status: ('wip' | 'done' | 'failed') }[]
} | { type: 'read_link'; links: {
  id: string
  url: string
  title: string
  status: ToolStatus
}[] } | { type: 'thinking'; key: string; blocks: {
  type: 'thinking'
  thinking: string
  signature?: string
  /** content_block_start 的时间；没有事件时间的历史块缺省 */
  startedAt?: number
  /** content_block_stop（或回复结束）的时间 */
  endedAt?: number
  /** 仅有耗时、没有事件时间时保存秒数。 */
  elapsedSeconds?: number
}[] } | { type: 'text'; key: string; markdown: string })[]
  /** 最后一个思考或工具块之后的正文；markdown 里在引用处插入了 [citation:N] */
  answer: { markdown: string; text: string } | null
  /** 正文引用可指向的全部来源，按编号排列 */
  sources: ({
  url: string
  title: string
  /** 优先使用服务端站点名，没有时使用域名（去掉 www.） */
  siteName: string
  /** 搜索结果为 RFC 3339，阅读链接为爬虫提取的原始日期 */
  publishedAt: string | null
  /** 明文摘要与站点图标；缺少元数据时为 null */
  snippet: string | null
  siteIcon: string | null
  /** 引用角标与搜索结果列表上的编号，从 1 开始 */
  index: number
})[]
  /** 搜索到的网页（去重），用于底部汇总与搜索结果列表 */
  searchResults: ({
  url: string
  title: string
  /** 优先使用服务端站点名，没有时使用域名（去掉 www.） */
  siteName: string
  /** 搜索结果为 RFC 3339，阅读链接为爬虫提取的原始日期 */
  publishedAt: string | null
  /** 明文摘要与站点图标；缺少元数据时为 null */
  snippet: string | null
  siteIcon: string | null
  /** 引用角标与搜索结果列表上的编号，从 1 开始 */
  index: number
})[]
})

